import{_ as a,c as n,a2 as r,o as t}from"./chunks/framework.rHWNTPhC.js";const v=JSON.parse('{"title":"Wahlvorstand-Service","description":"","frontmatter":{},"headers":[],"relativePath":"services/backend-services/wahlvorstand-service/index.md","filePath":"services/backend-services/wahlvorstand-service/index.md"}'),i={name:"services/backend-services/wahlvorstand-service/index.md"};function l(s,e,d,o,h,c){return t(),n("div",null,e[0]||(e[0]=[r('<h1 id="wahlvorstand-service" tabindex="-1">Wahlvorstand-Service <a class="header-anchor" href="#wahlvorstand-service" aria-label="Permalink to &quot;Wahlvorstand-Service&quot;">​</a></h1><p>Service für Themen im Zusammenhang mit Wahlvorständen und Anwesenheiten.</p><p>Jedes WahlvorstandsMitglied hat eine Funktion, die von der entsprechenden WahlbezirksArt und Wahlart abhängig ist. Der konkrete Funktionsname wird aktuell vom Service gemappt und bereitgestellt.</p><p><strong>Beispiel:</strong></p><ul><li><code>UWB.BTW.W</code> = Wahlvorsteher*in (Funktion W) der Bundestagswahl (Wahlart BTW) in einem Urnenwahlbezirk (Wahlbezirksart UWB)</li><li><code>BWB.BEB.SWB</code> = Stellvertretung Briefwahlvorsteher*in (Funktion SWB) des Bürgerentscheids (Wahlart BEB) in einem Briefwahlbezirk (Wahlbezirksart BWB)</li></ul><h2 id="abhangigkeiten" tabindex="-1">Abhängigkeiten <a class="header-anchor" href="#abhangigkeiten" aria-label="Permalink to &quot;Abhängigkeiten&quot;">​</a></h2><p>Folgende Services werden für den Betrieb benötigt:</p><ul><li>Basisdaten-Service</li><li>EAI-Service</li><li>Infomanagement-Service</li></ul><h2 id="daten-und-funktionen" tabindex="-1">Daten und Funktionen <a class="header-anchor" href="#daten-und-funktionen" aria-label="Permalink to &quot;Daten und Funktionen&quot;">​</a></h2><ul><li>Abrufen der Wahlvorstände der Wahlbezirke</li><li>Pflege der Anwesenheiten der Wahlvorstände</li></ul><h3 id="wahlart" tabindex="-1">Wahlart <a class="header-anchor" href="#wahlart" aria-label="Permalink to &quot;Wahlart&quot;">​</a></h3><p>Es gibt die folgenden Wahlarten</p><h3 id="wahlvorstand-abrufen" tabindex="-1">Wahlvorstand abrufen <a class="header-anchor" href="#wahlvorstand-abrufen" aria-label="Permalink to &quot;Wahlvorstand abrufen&quot;">​</a></h3><p>Die <code>getWahlvorstand()</code>-Methode stellt einen Mechanismus zum Abrufen von Wahlvorstandsinformationen bereit, der sowohl lokale- als auch remote-Datenabrufe unterstützt.</p><ul><li><p>Ist das optionale Flag <code>forceUpdate</code> auf true gesetzt, werden die aktuellsten remote-Daten abgerufen und die lokalen Daten überschrieben.</p></li><li><p>Durch die Implementierung eines Fallback-Mechanismus wird sichergestellt, dass der Client auch im Falle einer fehlenden Antwort eine valide Rückmeldung erhält.</p></li></ul>',15)]))}const b=a(i,[["render",l]]);export{v as __pageData,b as default};
